<?php $title="Reports";require "includes/header.php";$rev=$conn->query("SELECT COALESCE(SUM(amount),0)n FROM sales")->fetch_assoc()["n"];$orders=$conn->query("SELECT COUNT(*)n FROM sales")->fetch_assoc()["n"];$cust=$conn->query("SELECT COUNT(*)n FROM customers")->fetch_assoc()["n"];$stock=$conn->query("SELECT COALESCE(SUM(stock),0)n FROM bicycles")->fetch_assoc()["n"];?><div class="hero"><div class="orb"></div><h1>📊 SmartCycle Analytics</h1><p>Sales, products and customer intelligence.</p></div><div class="grid four"><?php foreach([["Revenue",money($rev)],["Orders",$orders],["Customers",$cust],["Units in Stock",$stock]] as $x):?><div class="card kpi"><div class="label"><?=$x[0]?></div><div class="value"><?=$x[1]?></div></div><?php endforeach;?></div><div class="grid two" style="margin-top:16px"><div class="card"><h3>Monthly Revenue</h3><div class="chartbox"><canvas id="a"></canvas></div></div><div class="card"><h3>Customer Mix</h3><div class="chartbox"><canvas id="b"></canvas></div></div></div><script>new Chart(document.getElementById("a"),{type:"bar",data:{labels:["Jan","Feb","Mar","Apr","May","Jun"],datasets:[{label:"Revenue",data:[48000,56000,62000,71000,82000,96000]}]},options:{responsive:true,maintainAspectRatio:false}});new Chart(document.getElementById("b"),{type:"doughnut",data:{labels:["Adventure","Commuter","Premium","Family","New Rider"],datasets:[{data:[28,25,18,14,15]}]},options:{responsive:true,maintainAspectRatio:false}});</script><?php require "includes/footer.php";?>